// Do not supply changes, replacements or manually copied values. On a version conflict, obtain a new complete file read and repeat this declared-field edit.
type ToolResult<T> = {ok: true; value: T; result_ref?: string} | {ok: false; error: string};
type Result<T> = Promise<ToolResult<T>>;
declare function unwrap<T>(result: ToolResult<T>): T;
declare const tools: {
  // Click a ref from the latest browser snapshot; stale refs are rejected.
  browser_click(args: { "ref": string }): Result<{ "action": string; "delivery": string; "text": string; "ref": string; "observation": string; "effect_verified": boolean; "page_url": string }>;
  // Fill and verify a textbox ref from the latest browser snapshot.
  browser_fill(args: { "ref": string; "value": string }): Result<{ "action": string; "delivery": string; "text": string; "ref": string; "value_length": number }>;
  // Navigate the current browser page to a user-authorized URL.
  browser_navigate(args: { "url": string /* length 1..* */ }): Result<{ "action": string; "delivery": string; "text": string; "url": string; "page_id": string; "generation": number; "http_status": number | null; "content_type": string; "previous_url": string }>;
  // Capture the currently bound page through the Research source and passage pipeline.
  browser_read(args: { "offset"?: number /* range 0..* */; "limit"?: number /* range 500..12000 */ }): Result<string>;
  // Scroll the bound page by a bounded amount.
  browser_scroll(args: { "direction": "up" | "down" | "left" | "right"; "amount": number /* range 1..20000 */ }): Result<{ "action": string; "delivery": string; "text": string; "ref": string; "observation": string; "effect_verified": boolean; "page_url": string }>;
  // Observe the bound page as bounded text and named interactive element refs.
  browser_snapshot(args: { "max_elements"?: number /* range 1..80 */; "max_text"?: number /* range 500..12000 */ }): Result<{ "page_id": string; "page_url": string; "generation": number; "text": string; "complete": boolean; "scope": string; "text_truncated": boolean; "elements_truncated": boolean; "elements": Array<{ "ref": string; "role": string; "name": string; "disabled": boolean; "context_id"?: string; "value": string | null; "checked": boolean | null }>; "contexts"?: Array<{ "id": string; "kind": string; "label": string; "basis": string }>; "file_controls"?: Array<{ "id": string; "name": string; "dom_id": string; "field_name": string; "group": string; "disabled": boolean }> }>;
  // List pages in tabs; page_url identifies the currently bound browser page.
  browser_tab_list(args: {  }): Result<{ "text": string; "page_url": string; "tabs": Array<{ "index": number; "page_id": string; "url": string; "title": string }> }>;
  // Open a new tab at a user-authorized URL.
  browser_tab_new(args: { "url": string /* length 1..* */ }): Result<{ "action": string; "delivery": string; "text": string; "url": string; "page_id": string; "generation": number; "http_status": number | null; "content_type": string }>;
  // Switch to a tab index from the latest tab list.
  browser_tab_switch(args: { "index": number /* range 0..* */ }): Result<{ "action": string; "delivery": string; "text": string; "index": number; "url": string }>;
  // Wait for one explicit bounded condition on the bound page.
  browser_wait(args: { "condition": "text" | "selector" | "url_contains"; "value": string; "timeout_ms": number /* range 100..30000 */ }): Result<{ "action": string; "condition": string; "matched": boolean; "page_url": string; "text": string }>;
  // Edit existing files with up to 8 exact replacements, preserving unrelated code. For replacements, omit content and base_result_ref. Create new files with content. For a whole-file update, use content plus base_result_ref. base_result_ref must be a complete read_file receipt from this task; changed versions are rejected. Include surrounding lines and the target text together in old_string of the same replacement so it matches one location uniquely. Preserve those surrounding lines in new_string. Separate replacement objects do not scope one another.
  // edit.content: Complete file text; preserve unrelated content. Prefer replacements for focused edits.
  // edit.base_result_ref: Only for content mode; omit this field with replacements. Use the latest complete read_file receipt reference. The reference belongs to the original outer Result; unwrap returns only file data. CodeMode example: const base=await tools.read_file({path:inputs.path}); const data=unwrap(base); then pass base.result_ref as base_result_ref.
  // edit.declared_fields: Copy only task-declared fields from complete browser receipts. Supply path and the original complete read's base_result_ref; do not supply content or changes.
  edit(args: { "path": string; "content"?: string; "base_result_ref"?: string; "declared_fields"?: true }): Result<string>;
  // Find bounded lexical reference hints for a simple symbol. This is not semantic resolution; use read_file before editing.
  find_references(args: { "symbol": string; "path"?: string }): Result<string>;
  // Search file contents for literal text before reading when the location is unknown. Uses packaged ripgrep. Defaults to literal, case-insensitive matching; set literal=false for regex, case_sensitive=true for exact case, include for one positive glob, exclude for positive globs to omit, and before_context/after_context for surrounding lines. Use rg braces for alternatives, e.g. include='*.{py,ts}'; comma-separated globs are not alternatives. Globs are relative to the workspace root even when path narrows the search. Exclude directories with an array such as exclude=['src/vendor/**']. Searches hidden and ignored files within the admitted workspace scope, excluding build/VCS directories and symlinks. CodeMode value is a page object with matches and explicit coverage; column_byte is one-based UTF-8 bytes. Read matched files for context.
  // grep.include: One rg glob string, not an array. Combine alternatives with braces, e.g. *.{py,ts}.
  grep(args: { "query": string; "path"?: string; "offset"?: number /* range 1..* */; "limit"?: number /* range 1..* */; "literal"?: boolean; "case_sensitive"?: boolean; "include"?: string; "exclude"?: Array<string>; "before_context"?: number /* range 0..* */; "after_context"?: number /* range 0..* */ }): Result<{ "query": string; "path": string; "include": string; "exclude": Array<string>; "literal": boolean; "case_sensitive": boolean; "has_more": boolean; "scan_complete": boolean; "offset": number /* range 1..* */; "limit": number /* range 1..* */; "before_context": number /* range 0..* */; "after_context": number /* range 0..* */; "next_offset": number /* range 0..* */; "matches": Array<{ "path": string; "text": string; "line": number /* range 1..* */; "column_byte": number /* range 1..* */ }>; "context": Array<{ "path": string; "text": string; "line": number /* range 1..* */; "relation": "before" | "after" | "between" }>; "coverage": { "files_admitted": number /* range 0..* */; "bytes_admitted": number /* range 0..* */; "oversized": number /* range 0..* */; "unreadable": number /* range 0..* */; "budget_limited": boolean } }>;
  // List files in a directory.
  list_dir(args: { "path"?: string }): Result<string>;
  // read a page's text; for PDFs, pages selects bounded page ranges
  open_url(args: { "url": string; "offset"?: number; "limit"?: number; "pages"?: string }): Result<string>;
  // Read one file. Large files are returned in complete-line pages. In CodeMode, value is an object: value.text is the page text (a string), with start_line, end_line, total_lines, next_offset and text_complete metadata.
  read_file(args: { "path": string; "offset"?: number /* range 1..* */; "limit"?: number /* range 1..* */ }): Result<{ "path": string; "text": string; "start_line": number /* range 1..* */; "end_line": number /* range 0..* */; "total_lines": number /* range 0..* */; "next_offset": number /* range 0..* */; "text_complete": boolean }>;
  // search within a source already opened with open_url; returns locators, offsets, and PDF pages
  source_search(args: { "url": string; "query": string; "limit"?: number }): Result<string>;
  // search the web for ranked results
  web_search(args: { "query": string }): Result<string>;
};
